def matches_wildcard(s, pattern):
    import re
    regex_chars = []
    for ch in pattern:
        if ch == '*':
            regex_chars.append('.*')
        elif ch == '?':
            regex_chars.append('.')
        else:
            regex_chars.append(re.escape(ch))
    regex = '^' + ''.join(regex_chars) + '$'
    return re.match(regex, s) is not None

