def is_valid_tags_with_attributes(s):
    stack = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] != '<':
            return False
        end = s.find('>', i)
        if end == -1:
            return False
        tag_content = s[i + 1:end]
        if tag_content.startswith('/'):
            word = tag_content[1:]
            if not word.isalpha() or not word.islower():
                return False
            if not stack or stack[-1] != word:
                return False
            stack.pop()
        else:
            space_idx = len(tag_content)
            for j, ch in enumerate(tag_content):
                if ch == ' ':
                    space_idx = j
                    break
            word = tag_content[:space_idx]
            if not word.isalpha() or not word.islower():
                return False
            stack.append(word)
        i = end + 1
    return not stack

