def sort_strings_by_length_then_alpha(words):
    from collections import defaultdict
    groups = defaultdict(list)
    for w in words:
        groups[len(w)].append(w)
    result = []
    for length in sorted(groups):
        result.extend(sorted(groups[length]))
    return result

