def peak_indices(lst):
    n = len(lst)
    if n < 3:
        return []
    result = []
    for i, (prev, cur, nxt) in enumerate(zip(lst, lst[1:], lst[2:])):
        if cur > prev and cur > nxt:
            result.append(i + 1)
    return result

