def build_multimap(pairs):
    grouped = {}
    for key, value in pairs:
        if key not in grouped:
            grouped[key] = []
        if value not in grouped[key]:
            grouped[key].append(value)
    return {key: sorted(values) for key, values in grouped.items()}

