import math

def digits_in_factorial(n):
    if n == 0 or n == 1:
        return 1
    total = 0.0
    for i in range(2, n + 1):
        total += math.log10(i)
    return int(total) + 1

def is_valid_scientific_notation(s):
    for i, ch in enumerate(s):
        if ch in "eE":
            mantissa, exponent = s[:i], s[i + 1:]
            break
    else:
        return False

    m = mantissa
    if m and m[0] in "+-":
        m = m[1:]
    if "." in m:
        int_part, _, frac_part = m.partition(".")
    else:
        int_part, frac_part = m, "1"
    if not int_part.isdigit() or not frac_part.isdigit():
        return False

    e = exponent
    if e and e[0] in "+-":
        e = e[1:]
    return bool(e) and e.isdigit()
